            if nm in sel: continue
            B=np.column_stack([pool[s] for s in sel]+[col])
            c,_,_,_=np.linalg.lstsq(B,dv_dt,rcond=None)
            rr=np.mean((dv_dt-B@c)**2)/np.var(dv_dt)
